async fn list_instances(
    ctx: &Context<'_>,
    args: ListInstancesArgs,
) -> anyhow::Result<Box<dyn SerializableOutput>> {
    let names = ctx
        .names(&[("project", args.project.as_deref()), ("zone", args.zone.as_deref())]);
    let request = ::origincloud_compute::v1beta1::ListInstancesRequest {
        parent: String::new(),
        page_size: args.page_size.unwrap_or_default(),
        page_token: args.page_token.clone().unwrap_or_default(),
    };
    let client = ctx.client()?;
    let paging = args.page_size.is_some() || args.page_token.is_some();
    let parents: Vec<String> = match args.zone.as_deref() {
        Some(_) => vec![names.name("projects/{project}/zones/{zone}", None) ?],
        None => {
            if paging {
                anyhow::bail!(
                    "--page-size and --page-token list one page of one zone: they need --zone"
                );
            }
            names.check_without("projects/{project}/zones/{zone}", "zone")?;
            let mut parents = Vec::new();
            for zone in zones(ctx, "compute").await? {
                parents
                    .push(
                        names
                            .with_part("zone", &zone)
                            .name("projects/{project}/zones/{zone}", None)?,
                    );
            }
            parents
        }
    };
    if paging {
        let mut request = request;
        request.parent = parents.into_iter().next().unwrap_or_default();
        let page = call_list_instances(&client, request).await.map_err(api_error)?;
        return list_json(&page, "instances");
    }
    let mut items = Vec::new();
    for parent in parents {
        let mut request = request.clone();
        request.parent = parent;
        loop {
            let page = call_list_instances(&client, request.clone())
                .await
                .map_err(api_error)?;
            items.extend(page.instances);
            if page.next_page_token.is_empty() {
                break;
            }
            request.page_token = page.next_page_token;
        }
    }
    list_json(
        &::origincloud_compute::v1beta1::ListInstancesResponse {
            instances: items,
            ..::core::default::Default::default()
        },
        "instances",
    )
}
